def update_research_session(id, task_description=None, initial_confidence=None, enable_multi_layer=None, enable_fallbacks=None, default_dimensions=None, disciplinary_tags=None, attribution=None, status=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0281000" if __import__("os").path.isdir("./environment_mix/0281000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- Observability / request logging + basic rate/quota enforcement (only if a log file exists) ----
    def _pick_log_file():
        for fname in ("api_requests.json", "request_logs.json", "usage_logs.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                return fname
        return None

    def _parse_ts(x):
        if not isinstance(x, str):
            return None
        try:
            s = x[:-1] if x.endswith("Z") else x
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _enforce_limits(log_rows, endpoint):
        # Per-endpoint: 60/min rate limit, 10k/day quota
        now = datetime.datetime.utcnow()
        one_min_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)
        recent = 0
        daily = 0
        for r in log_rows:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= one_min_ago:
                recent += 1
            if ts >= day_ago:
                daily += 1
        if recent >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit="60/min", window_seconds=60)
        if daily >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", limit="10000/day", window_seconds=86400)
        return None

    endpoint = "update_research_session"
    log_file = _pick_log_file()
    log_rows = _load(log_file) if log_file else None

    # Enforce limits before mutation work, but only when logging is enabled/persistable
    if isinstance(log_rows, list):
        limited = _enforce_limits(log_rows, endpoint)
        if limited:
            # log refused request
            log_rows.append({
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "timestamp": _now(),
                "status": "error",
                "error_code": limited["error"]["code"],
                "latency_ms": int((time.time() - t0) * 1000),
                "resource_id": id
            })
            _save(log_file, log_rows)
            return limited

    # ---- Input validation (schema-aligned) ----
    if not isinstance(id, str) or not id.strip():
        err = _err("VALIDATION_ERROR", "Field 'id' must be a non-empty string.", field="id")
        if isinstance(log_rows, list):
            log_rows.append({
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "timestamp": _now(),
                "status": "error",
                "error_code": err["error"]["code"],
                "latency_ms": int((time.time() - t0) * 1000),
                "resource_id": id
            })
            _save(log_file, log_rows)
        return err

    if task_description is not None and not isinstance(task_description, str):
        err = _err("VALIDATION_ERROR", "Field 'task_description' must be a string.", field="task_description")
        if isinstance(log_rows, list):
            log_rows.append({
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "timestamp": _now(),
                "status": "error",
                "error_code": err["error"]["code"],
                "latency_ms": int((time.time() - t0) * 1000),
                "resource_id": id
            })
            _save(log_file, log_rows)
        return err

    def _validate_conf_vec(vec, field):
        if not isinstance(vec, list):
            return _err("VALIDATION_ERROR", f"Field '{field}' must be an array of 4 numbers in [0,1].", field=field)
        if len(vec) != 4:
            return _err(
                "VALIDATION_ERROR",
                f"Rejected by rule json_array_length({field}) = 4.",
                field=field,
                rule=f"json_array_length({field}) = 4",
                required_length=4
            )
        for i, v in enumerate(vec):
            if not isinstance(v, (int, float)):
                return _err("VALIDATION_ERROR", f"Field '{field}[{i}]' must be a number.", field=field, index=i)
            if v < 0 or v > 1:
                return _err("VALIDATION_ERROR", f"Field '{field}[{i}]' must be between 0 and 1.", field=field, index=i, minimum=0, maximum=1)
        return None

    if initial_confidence is not None:
        e = _validate_conf_vec(initial_confidence, "initial_confidence")
        if e:
            if isinstance(log_rows, list):
                log_rows.append({
                    "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                    "endpoint": endpoint,
                    "timestamp": _now(),
                    "status": "error",
                    "error_code": e["error"]["code"],
                    "latency_ms": int((time.time() - t0) * 1000),
                    "resource_id": id
                })
                _save(log_file, log_rows)
            return e

    if enable_multi_layer is not None and not isinstance(enable_multi_layer, bool):
        err = _err("VALIDATION_ERROR", "Field 'enable_multi_layer' must be boolean.", field="enable_multi_layer")
        if isinstance(log_rows, list):
            log_rows.append({
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "timestamp": _now(),
                "status": "error",
                "error_code": err["error"]["code"],
                "latency_ms": int((time.time() - t0) * 1000),
                "resource_id": id
            })
            _save(log_file, log_rows)
        return err

    if enable_fallbacks is not None and not isinstance(enable_fallbacks, bool):
        err = _err("VALIDATION_ERROR", "Field 'enable_fallbacks' must be boolean.", field="enable_fallbacks")
        if isinstance(log_rows, list):
            log_rows.append({
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "timestamp": _now(),
                "status": "error",
                "error_code": err["error"]["code"],
                "latency_ms": int((time.time() - t0) * 1000),
                "resource_id": id
            })
            _save(log_file, log_rows)
        return err

    def _validate_str_list(val, field, nullable_ok=True):
        if val is None:
            return None
        if not isinstance(val, list):
            return _err("VALIDATION_ERROR", f"Field '{field}' must be an array of strings.", field=field)
        for i, x in enumerate(val):
            if not isinstance(x, str):
                return _err("VALIDATION_ERROR", f"Field '{field}[{i}]' must be a string.", field=field, index=i)
        return None

    if default_dimensions is not None:
        e = _validate_str_list(default_dimensions, "default_dimensions")
        if e:
            if isinstance(log_rows, list):
                log_rows.append({
                    "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                    "endpoint": endpoint,
                    "timestamp": _now(),
                    "status": "error",
                    "error_code": e["error"]["code"],
                    "latency_ms": int((time.time() - t0) * 1000),
                    "resource_id": id
                })
                _save(log_file, log_rows)
            return e
        # Business rule: must include these when provided
        dims_set = set(default_dimensions)
        missing = [d for d in ("Potential Biases", "Knowledge Gaps") if d not in dims_set]
        if missing:
            e = _err(
                "VALIDATION_ERROR",
                "Rejected by rule: default_dimensions must include 'Potential Biases' and 'Knowledge Gaps' when provided.",
                field="default_dimensions",
                rule="default_dimensions contains 'Potential Biases' and 'Knowledge Gaps'",
                missing=missing
            )
            if isinstance(log_rows, list):
                log_rows.append({
                    "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                    "endpoint": endpoint,
                    "timestamp": _now(),
                    "status": "error",
                    "error_code": e["error"]["code"],
                    "latency_ms": int((time.time() - t0) * 1000),
                    "resource_id": id
                })
                _save(log_file, log_rows)
            return e
        if len(default_dimensions) < 2:
            e = _err(
                "VALIDATION_ERROR",
                "Rejected by rule json_array_length(default_dimensions) >= 2.",
                field="default_dimensions",
                rule="json_array_length(default_dimensions) >= 2",
                minimum_length=2
            )
            if isinstance(log_rows, list):
                log_rows.append({
                    "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                    "endpoint": endpoint,
                    "timestamp": _now(),
                    "status": "error",
                    "error_code": e["error"]["code"],
                    "latency_ms": int((time.time() - t0) * 1000),
                    "resource_id": id
                })
                _save(log_file, log_rows)
            return e

    if disciplinary_tags is not None:
        e = _validate_str_list(disciplinary_tags, "disciplinary_tags")
        if e:
            if isinstance(log_rows, list):
                log_rows.append({
                    "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                    "endpoint": endpoint,
                    "timestamp": _now(),
                    "status": "error",
                    "error_code": e["error"]["code"],
                    "latency_ms": int((time.time() - t0) * 1000),
                    "resource_id": id
                })
                _save(log_file, log_rows)
            return e

    if attribution is not None:
        e = _validate_str_list(attribution, "attribution")
        if e:
            if isinstance(log_rows, list):
                log_rows.append({
                    "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                    "endpoint": endpoint,
                    "timestamp": _now(),
                    "status": "error",
                    "error_code": e["error"]["code"],
                    "latency_ms": int((time.time() - t0) * 1000),
                    "resource_id": id
                })
                _save(log_file, log_rows)
            return e

    allowed_statuses = ["initialized", "decomposed", "hypotheses_generated", "completed", "failed", "archived"]
    if status is not None:
        if not isinstance(status, str) or status not in allowed_statuses:
            err = _err("VALIDATION_ERROR", "Field 'status' must be one of the allowed lifecycle values.", field="status", allowed=allowed_statuses)
            if isinstance(log_rows, list):
                log_rows.append({
                    "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                    "endpoint": endpoint,
                    "timestamp": _now(),
                    "status": "error",
                    "error_code": err["error"]["code"],
                    "latency_ms": int((time.time() - t0) * 1000),
                    "resource_id": id
                })
                _save(log_file, log_rows)
            return err

    # ---- Load session and enforce lifecycle rules ----
    sessions = _load("research_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    sess = None
    idx = None
    for i, r in enumerate(sessions):
        if isinstance(r, dict) and r.get("id") == id:
            sess = r
            idx = i
            break

    if sess is None:
        err = _err("NOT_FOUND", "Research session not found.", id=id)
        if isinstance(log_rows, list):
            log_rows.append({
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "timestamp": _now(),
                "status": "error",
                "error_code": err["error"]["code"],
                "latency_ms": int((time.time() - t0) * 1000),
                "resource_id": id
            })
            _save(log_file, log_rows)
        return err

    current_status = sess.get("status")
    if current_status == "archived":
        # No mutations allowed on archived sessions
        err = _err("CONFLICT", "Archived sessions cannot be modified.", id=id, status=current_status)
        if isinstance(log_rows, list):
            log_rows.append({
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "timestamp": _now(),
                "status": "error",
                "error_code": err["error"]["code"],
                "latency_ms": int((time.time() - t0) * 1000),
                "resource_id": id
            })
            _save(log_file, log_rows)
        return err

    transitions = {
        "initialized": ["decomposed", "failed", "archived"],
        "decomposed": ["hypotheses_generated", "failed", "archived"],
        "hypotheses_generated": ["completed", "failed", "archived"],
        "completed": ["archived"],
        "failed": ["archived"],
        "archived": []
    }

    # NOTE: vendor description says illegal transitions -> VALIDATION_ERROR (not INVALID_TRANSITION)
    if status is not None and status != current_status:
        allowed = transitions.get(current_status, [])
        if status not in allowed:
            err = _err(
                "VALIDATION_ERROR",
                "Illegal status transition.",
                field="status",
                from_status=current_status,
                to_status=status,
                allowed_transitions=allowed
            )
            if isinstance(log_rows, list):
                log_rows.append({
                    "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                    "endpoint": endpoint,
                    "timestamp": _now(),
                    "status": "error",
                    "error_code": err["error"]["code"],
                    "latency_ms": int((time.time() - t0) * 1000),
                    "resource_id": id
                })
                _save(log_file, log_rows)
            return err

    # ---- Apply updates (NO SUCCESS WITHOUT EFFECT: require at least one change) ----
    changed = False
    def _set(field, value):
        nonlocal changed
        if value is None:
            return
        if sess.get(field) != value:
            sess[field] = value
            changed = True

    _set("task_description", task_description)
    _set("initial_confidence", initial_confidence)
    _set("enable_multi_layer", enable_multi_layer)
    _set("enable_fallbacks", enable_fallbacks)
    _set("default_dimensions", default_dimensions)
    _set("disciplinary_tags", disciplinary_tags)
    _set("attribution", attribution)
    if status is not None and status != current_status:
        sess["status"] = status
        changed = True

    if not changed:
        err = _err("CONFLICT", "No changes to apply.", id=id)
        if isinstance(log_rows, list):
            log_rows.append({
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "timestamp": _now(),
                "status": "error",
                "error_code": err["error"]["code"],
                "latency_ms": int((time.time() - t0) * 1000),
                "resource_id": id
            })
            _save(log_file, log_rows)
        return err

    # Ensure invariants that must always hold
    if sess.get("root_node_key") != "n0":
        err = _err("VALIDATION_ERROR", "Rejected by rule root_node_key = 'n0'.", field="root_node_key", rule="root_node_key = 'n0'")
        if isinstance(log_rows, list):
            log_rows.append({
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": endpoint,
                "timestamp": _now(),
                "status": "error",
                "error_code": err["error"]["code"],
                "latency_ms": int((time.time() - t0) * 1000),
                "resource_id": id
            })
            _save(log_file, log_rows)
        return err

    # parameter_status must include keys P1.0..P1.29 (nullable allowed)
    ps = sess.get("parameter_status")
    if not isinstance(ps, dict):
        ps = {}
    missing_keys = []
    for i in range(30):
        k = f"P1.{i}"
        if k not in ps:
            missing_keys.append(k)
            ps[k] = None
    if missing_keys:
        sess["parameter_status"] = ps
        changed = True

    sess["updated_at"] = _now()
    sessions[idx] = sess
    _save("research_sessions.json", sessions)

    result = {"session": sess}

    if isinstance(log_rows, list):
        log_rows.append({
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": "success",
            "latency_ms": int((time.time() - t0) * 1000),
            "resource_id": id
        })
        _save(log_file, log_rows)

    return result

def list_query_executions(session_id=None, status=None, started_after=None, started_before=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0281000" if __import__("os").path.isdir("./environment_mix/0281000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _log_attempt(status_code, latency_ms):
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json", "api_requests.json"):
            p = os.path.join(_DB, fname)
            if os.path.exists(p):
                rows = _load(fname)
                if not isinstance(rows, list):
                    rows = []
                rows.append({
                    "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
                    "endpoint": "list_query_executions",
                    "status": status_code,
                    "latency_ms": latency_ms,
                    "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
                    "resource_id": session_id,
                })
                _save(fname, rows)
                break

    t0 = datetime.datetime.utcnow()

    # Defaults/validation
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        latency = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        _log_attempt("VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200", field="page_size")

    if session_id is not None and (not isinstance(session_id, str) or not session_id.strip()):
        latency = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        _log_attempt("VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "session_id must be a non-empty string when provided", field="session_id")

    allowed_status = ["running", "succeeded", "succeeded_with_fallbacks", "failed", "cancelled"]
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            latency = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
            _log_attempt("VALIDATION_ERROR", latency)
            return _err("VALIDATION_ERROR", "status filter must be one of allowed values", field="status", allowed=allowed_status)

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return "ERR"
        try:
            # accept trailing Z
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return "ERR"

    dt_after = _parse_dt(started_after, "started_after")
    if dt_after == "ERR":
        latency = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        _log_attempt("VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "started_after must be an ISO 8601 date-time string", field="started_after")

    dt_before = _parse_dt(started_before, "started_before")
    if dt_before == "ERR":
        latency = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        _log_attempt("VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "started_before must be an ISO 8601 date-time string", field="started_before")

    if dt_after and dt_before and dt_after > dt_before:
        latency = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        _log_attempt("VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "started_after must be <= started_before", field="started_after")

    # Access control: no explicit auth model present in schema; treat as permitted.
    # If session_id is provided, ensure it exists (filtering by a non-existent session returns empty set per contract?);
    # Here, treat it as a filter; if session doesn't exist, return empty list (read with filters match nothing).
    sessions = _load("research_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    session_exists = True
    if session_id is not None:
        session_exists = any(isinstance(s, dict) and s.get("id") == session_id for s in sessions)
        if not session_exists:
            latency = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
            _log_attempt("OK", latency)
            return {"data": [], "meta": {"total": 0, "page_size": page_size, "has_more": False, "next_page_token": None}}

    executions = _load("query_executions.json")
    if not isinstance(executions, list):
        executions = []

    # Filter
    def _row_dt(row):
        s = row.get("started_at")
        if not isinstance(s, str):
            return None
        try:
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    filtered = []
    for r in executions:
        if not isinstance(r, dict):
            continue
        if session_id is not None and r.get("session_id") != session_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        dtr = _row_dt(r)
        if dt_after and (dtr is None or dtr < dt_after):
            continue
        if dt_before and (dtr is None or dtr > dt_before):
            continue
        filtered.append(r)

    # Sort newest first by started_at then created_at
    def _sort_key(r):
        d1 = _row_dt(r) or datetime.datetime.min
        c = r.get("created_at")
        try:
            cc = datetime.datetime.fromisoformat((c[:-1] if isinstance(c, str) and c.endswith("Z") else c)) if isinstance(c, str) else datetime.datetime.min
        except Exception:
            cc = datetime.datetime.min
        return (d1, cc)

    filtered.sort(key=_sort_key, reverse=True)

    # Pagination via page_token = base64(json({"offset": int}))
    offset = 0
    if page_token is not None:
        if not isinstance(page_token, str) or not page_token:
            latency = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
            _log_attempt("VALIDATION_ERROR", latency)
            return _err("VALIDATION_ERROR", "page_token must be a non-empty string when provided", field="page_token")
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            offset = int(obj.get("offset", 0))
            if offset < 0:
                raise ValueError("offset<0")
        except Exception:
            latency = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
            _log_attempt("VALIDATION_ERROR", latency)
            return _err("VALIDATION_ERROR", "invalid page_token", field="page_token")

    total = len(filtered)
    page = filtered[offset:offset + page_size]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_token = None
    if has_more:
        next_token = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("utf-8").rstrip("=")

    latency = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
    _log_attempt("OK", latency)
    return {
        "data": page,
        "meta": {
            "total": total,
            "page_size": page_size,
            "has_more": has_more,
            "next_page_token": next_token
        }
    }

def get_query_execution(id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0281000" if __import__("os").path.isdir("./environment_mix/0281000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _log(status_code, resource_id=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": "get_query_execution",
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        }
        if resource_id is not None:
            row["resource_id"] = resource_id
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json", "api_requests.json"):
            p = os.path.join(_DB, fname)
            if os.path.exists(p):
                rows = _load(fname)
                if not isinstance(rows, list):
                    rows = []
                rows.append(row)
                _save(fname, rows)
                break

    if not isinstance(id, str) or not id.strip():
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string", field="id")

    wanted = id.strip()
    executions = _load("query_executions.json")
    if not isinstance(executions, list):
        executions = []

    row = None
    for r in executions:
        if isinstance(r, dict) and r.get("id") == wanted:
            row = r
            break

    # Relaxed behaviour: if caller passes a research_session id, return the most recent execution for that session
    if row is None:
        latest = None
        latest_ts = None
        for r in executions:
            if isinstance(r, dict) and r.get("session_id") == wanted:
                ts = r.get("started_at") or r.get("created_at") or ""
                if not isinstance(ts, str):
                    ts = ""
                if latest is None or ts > (latest_ts or ""):
                    latest = r
                    latest_ts = ts
        if latest is not None:
            row = latest

    if row is None:
        _log("NOT_FOUND", resource_id=wanted)
        return _err("NOT_FOUND", "query execution not found", id=wanted)

    _log("OK", resource_id=row.get("id"))
    return {"data": row}
